parameters.jsCode:
// Flatten monday item into a friendly object.
const item = $input.first().json.data?.items?.[0];
if (!item) throw new Error('item not found');
const col = (id) => item.column_values.find(c => c.id === id);
const text = (c) => c?.text?.trim() || '';
const pulseId = $('Webhook: /marketa-draft').first().json.body.pulseId;
return [{
  json: {
    pulseId: String(pulseId),
    title: item.name,
    brief: text(col('long_text_mm3grk84')),
    target_keyword: text(col('text_mm3gzj88')),
    industry: text(col('dropdown_mm3gb7wm')) || 'general'
  }
}];

