parameters.jsCode:
// Build the Claude prompt: voice guide + brief + retrieved chunks.
const meta = $('Normalize item').first().json;
const chunks = $('Supabase: retrieve chunks').all().map(i => i.json);
const voice = $('Fetch voice guide').first()?.json?.body || '(no voice guide)';
const context = chunks.map((c, i) => `--- Source ${i+1} (id: ${c.source_id}) ---\n${c.body}`).join('\n\n');
return [{
  json: {
    ...meta,
    voice,
    context,
    source_ids: chunks.map(c => c.source_id)
  }
}];

const draft = $input.first().json.content?.[0]?.text || '';
const meta = $('Normalize item').first().json;
return [{ json: { pulseId: meta.pulseId, draft } }];

